    { ...{"id":"step-2","title":"增加字段校验","goal":"用 validator 拒绝空白值，成功后才处理业务提交。","why":"字段错误由 Item 传给 LineEdit，在输入下方展示并关联到输入元素，无需额外的提示图标。","instruction":"先空值提交，再填写姓名并提交。","expected":"空值在姓名字段下方显示错误，有效值进入成功回调；三种风格保留相同的标签与错误关联。","changes":["用 validator 拒绝空白值，成功后才处理业务提交。"],"sourceCode":"import { useState } from \"react\";\nimport { css } from \"@crab-dev/css\";\nimport token from \"@crab-dev/rc-token-semantic\";\nimport Form, { Item, useForm, RuleType } from \"@crab-dev/rc-form\";\nimport LineEdit from \"@crab-dev/rc-line-edit\";\nimport Button from \"@crab-dev/rc-button\";\nconst layout = css`\n    display: grid;\n    gap: ${token.space[\"group-gap\"]};\n`;\nexport default function Example() {\n    const [form] = useForm<{\n        name: string;\n    }>();\n    const [result, setResult] = useState(\"\");\n    return (\n        <div className={layout}>\n            <Form\n                form={form}\n                defaultValue={{\n                    name: \"\",\n                }}\n                onSubmitSuccess={async (record) => {\n                    setResult(record.name);\n                }}\n            >\n                <Item\n                    name=\"name\"\n                    label=\"姓名\"\n                    labelPlacement=\"control\"\n                    supportingText=\"请填写真实姓名，最多 30 字。\"\n                    required\n                    rules={[\n                        {\n                            type: RuleType.ERROR,\n                            validator: async () => {\n                                if (!form.getFieldsValue().name?.trim())\n                                    throw new Error(\"请输入姓名\");\n                            },\n                        },\n                    ]}\n                >\n                    <LineEdit maxLength={30} />\n                </Item>\n                <Button onClick={() => void form.submit()}>校验并提交</Button>\n            </Form>\n            <output>提交姓名：{result || \"尚未通过校验\"}</output>\n        </div>\n    );\n}\n"}, preview: { kind: "inline", load: () => import("../examples/rc-form/step-2.js") } }
